update public.vocabulary_items v set translation_he = 'לחוץ, מתוח'
from public.topics t
where t.id = v.topic_id and t.slug = 'emotions-feelings' and v.headword = 'nervous' and v.translation_he = 'עצבני';

-- The same word inside that topic's exercises (multiple choice prompt, match pair).
update public.exercises e set content = replace(e.content::text, 'עצבני', 'לחוץ')::jsonb
from public.topics t
where t.id = e.topic_id and t.slug = 'emotions-feelings' and e.content::text like '%עצבני%';

-- Check: words per topic after the seed.
select t.slug, count(*) as words
from public.vocabulary_items v join public.topics t on t.id = v.topic_id
where t.slug in ('numbers', 'colors', 'family', 'greetings', 'time-days', 'emotions-feelings', 'shopping', 'hobbies', 'relationships') and v.status = 'published'
group by t.slug order by t.slug;
